(function(){
  var btn=document.getElementById('cb'), pre=document.getElementById('dt');
  if(!btn||!pre) return;
  function hotovo(){btn.classList.add('copied');btn.textContent='\u2713';setTimeout(function(){btn.classList.remove('copied');btn.textContent='\u29C9';},1800);}
  btn.addEventListener('click',function(){
    var s=pre.innerText.trim();
    if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(s).then(hotovo,function(){});return;}
    try{var r=document.createRange();r.selectNodeContents(pre);var sel=window.getSelection();sel.removeAllRanges();sel.addRange(r);
        if(document.execCommand('copy')) hotovo();}catch(e){}
  });
})();
(function(){
  // navratova cesta: puvodni stranka, nebo ?next= (jen relativni cesta)
  var r=location.pathname+location.search;
  try{ var nx=new URLSearchParams(location.search).get('next'); if(nx && /^\/[^\/\\\s]\S*$|^\/$/.test(nx)) r=nx; }catch(e){}
  if(r.charAt(0)!=='/'||r.charAt(1)==='/'||r.charAt(1)==='\\') r='/';
  var t0=Date.now(), wt=document.getElementById('wt'), hotovo=false;
  function ukaz(){ wt.textContent=m.w.replace('%s',Math.round((Date.now()-t0)/1000)); }
  ukaz(); var tik=setInterval(function(){ if(!hotovo) ukaz(); },1000);
  var presmerovano=false;
  function dal(){ if(presmerovano) return; presmerovano=true; hotovo=true; clearInterval(tik); location.replace(r); }
  var w=document.getElementById('wgp-pow');
  w.addEventListener('serververification',function(e){ var d=e.detail; if(d&&(d.verified===true||d.success===true)) dal(); });
  function konec(){ hotovo=true; clearInterval(tik); wt.textContent=m.fe;
    var sp=document.querySelector('#wr .spin'); if(sp) sp.style.display='none';
    document.getElementById('bt').style.display='inline-block'; }
  // WGP 2026-10-04 vecer: vyprseni ani chyba neni konec. Narocna PoW trva i desitky sekund a vyzva
  //   mezitim muze vyprset - widget pak hlasi 'expired', i kdyz server reseni prijal (po obnoveni
  //   pak web projde hned). Nejdriv zjistit, jestli pristup uz je (puvodni adresa nevraci 401),
  //   jinak tise zacit znovu; vzdat az po 3 pokusech.
  var pokusy=0, zkousim=false;
  function znovu(){
    if(presmerovano||zkousim) return; zkousim=true;
    fetch(r,{method:'HEAD',credentials:'same-origin',cache:'no-store',redirect:'manual'})
      .then(function(x){ return x.status!==401; },function(){ return false; })
      .then(function(ok){ zkousim=false; if(ok){ dal(); return; }
        if(++pokusy>3){ konec(); return; }
        try{ w.reset(); setTimeout(function(){ try{ w.verify(); }catch(e){ konec(); } },300); }catch(e){ konec(); } });
  }
  w.addEventListener('statechange',function(e){
    var s=e.detail&&e.detail.state;
    if(s==='verified') dal();
    if(s==='error'||s==='expired') znovu();
  });
})();
